def adjacent_transposition_generators' (n : ℕ) : Set (Equiv.Perm (Fin n)) :=
  (fun i : Fin n => Equiv.swap i (i + 1)) '' {i : Fin n | i.val < n - 1}

theorem adjacent_transpositions_generate_symmetric_group_alt (n : ℕ) (hn : n ≥ 2) :
  Subgroup.closure (adjacent_transposition_generators' n) = (⊤ : Subgroup (Equiv.Perm (Fin n))) := by sorry

