open Real Matrix

theorem dihedral_matrix_relation (n : ℕ) (hn : 3 ≤ n) :
  let θ := 2 * π / (n : ℝ)
  let r := !![cos θ, -sin θ;
              sin θ, cos θ]
  let h := !![1, 0;
              0, -1]
  r * h * r = h := by sorry

